rule.definition:
if(
  and(
    #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12219631"(ri!status),
    #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12219631"(ri!userAction),
    #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12219631"(ri!isActive),
    #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12219631"(ri!username)
  ),
  {},
  #"SYSTEM_SYSRULES_queryEntity_v2"(
    entity: #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12334105",
    query: {
      #"SYSTEM_SYSRULES_query"(
        logicalExpression: #"SYSTEM_SYSRULES_queryLogicalExpression"(
          operator: "AND",
          filters: {
            #"SYSTEM_SYSRULES_queryFilter"(
              field: "status",
              operator: "in",
              value: ri!status,
              applyWhen: not(
                isnull(
                  ri!status
                )
              )
            ),
            #"SYSTEM_SYSRULES_queryFilter"(
              field: "userAction",
              operator: "=",
              value: ri!userAction,
              applyWhen: not(
                isnull(
                  ri!userAction
                )
              )
            ),
            #"SYSTEM_SYSRULES_queryFilter"(
              field: "isActive",
              operator: "=",
              value: ri!isActive,
              applyWhen: not(
                isnull(
                  ri!isActive
                )
              )
            ),
            #"SYSTEM_SYSRULES_queryFilter"(
              field: "userName",
              operator: "in",
              value: ri!username,
              applyWhen: not(
                isnull(
                  ri!username
                )
              )
            )
          },
          ignoreFiltersWithEmptyValues: true
        ),
        pagingInfo: if(
          a!isNullOrEmpty(ri!pagingInfo),
          #"SYSTEM_SYSRULES_pagingInfo"(
            startIndex: 1,
            batchSize: -1
          ),
          ri!pagingInfo
        )
      )
    }
  ).data
)
